<?php get_header(); ?><main id="main-content" class="slateframe-main"><header class="slateframe-page-header"><div class="slateframe-shell"><?php the_archive_title('<h1 class="slateframe-page-title">','</h1>'); the_archive_description('<div>','</div>'); ?></div></header><div class="slateframe-shell slateframe-grid"><?php if(have_posts()):while(have_posts()):the_post();?><article <?php post_class('slateframe-card'); ?>><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><p><?php slateframe_posted_on(); ?></p><?php the_excerpt(); ?></article><?php endwhile;else:?><p><?php esc_html_e('Nothing found.','slateframe'); ?></p><?php endif;?></div><div class="slateframe-shell"><?php slateframe_pagination(); ?></div></main><?php get_footer(); ?>